// Some portions generated by Claude
/**
 * Hub-and-satellite organization. A satellite is a node whose only link to the rest of the drawn graph is one
 * neighbour (its anchor), including the small chains hanging from it (a product and its label). Satellites are
 * peeled off, the remaining skeleton is laid out by the force layout with a halo reserved around every hub, and the
 * satellites are fanned back on the side of their anchor that faces away from its skeleton neighbours, grouped by
 * predicate and type. Hubs stay apart; their leaves show which cards belong to them.
 */
import {RDF_TYPE} from './graph-canvas-scope.ts';
import {classHubsOf} from './graph-class-links.ts';
import {segmentIntersectsBounds} from './graph-curve-collision.ts';
import {graphNodeSize} from './graph-geometry.ts';
import {layoutNodeFixed} from './graph-layout-topology.ts';
import {LAYOUT_SPACING as gap} from './graph-layout-spacing.ts';
import type {Graph, GraphNode, PointerPosition} from './graph-types.ts';
import type {LayoutOptions} from './graph-layout-engine.ts';

/** A hanging subtree larger than this is a community of its own and stays in the skeleton. */
export const SATELLITE_SUBTREE_LIMIT = 8;
/** Widest arc a fan may take around its anchor. */
const FAN_SPAN = Math.PI * 1.1;
/** Widest arc for the fan of a satellite (it must keep pointing away from the satellite's own anchor). */
const NESTED_FAN_SPAN = Math.PI * 0.8;
const MIN_FAN_RADIUS = 110;
/** Side of the square the force layout keeps clear around a hub, relative to its fan radius. */
const HALO_SCALE = 1.5;
/** Satellites above this count go on staggered rings. */
const SINGLE_RING_LIMIT = 12;
/** Angular margin kept between a fan and the anchor's other neighbours. */
const FAN_MARGIN = 0.5;
/** Linked hubs stay at least this many times their longest spoke apart, so each hub's satellites read as its own. */
const HUB_SEPARATION = 1.3;

export type PeeledGraph = {
  skeleton: Graph;
  /** satellite id → anchor id */
  anchorOf: Map<string, string>;
  /** anchor id → satellite ids */
  satellitesOf: Map<string, string[]>;
  /** skeleton node id → side of the square reserved for it in the force layout */
  halos: Map<string, number>;
  /** node id → room its fan takes (see `FanGeometry`) */
  fans: Map<string, FanGeometry>;
  /** classes with many instances; they sit among their instances instead of pulling the layout */
  classHubs: Set<string>;
};

/** Room a node's fan takes, its own sub-fans included. */
export type FanGeometry = {
  /** spoke length from the node to its satellites */
  radius: number;
  /** width the node and its fan occupy sideways on its anchor's arc */
  lateral: number;
  /** how far beyond the node its fan reaches outward (0 for a node without satellites) */
  reach: number;
};

type Adjacency = {index: Map<string, number>; neighbors: Set<number>[]};

function adjacency(graph: Graph, skip?: (edge: Graph['edges'][number]) => boolean): Adjacency {
  const index = new Map(graph.nodes.map((node, i) => [node.id, i]));
  const neighbors = graph.nodes.map(() => new Set<number>());
  for (const edge of graph.edges) {
    if (skip?.(edge)) continue;
    const a = index.get(edge.source), b = index.get(edge.target);
    if (a === undefined || b === undefined || a === b) continue;
    neighbors[a].add(b);
    neighbors[b].add(a);
  }
  return {index, neighbors};
}



/** One node linked to every other node and nothing else: `computeNetworkLayout` draws it as a sunflower. */
export function isPureStar(graph: Graph) {
  if (graph.nodes.length < 20) return false;
  const {neighbors} = adjacency(graph);
  const hubs = neighbors.filter(set => set.size === graph.nodes.length - 1).length;
  return hubs === 1 && neighbors.every(set => set.size === 1 || set.size === graph.nodes.length - 1);
}

/** Spoke length a fan of these cards takes around its anchor when it may use the widest arc. */
export function fanRadius(anchor: GraphNode, satellites: readonly GraphNode[]) {
  const arc = satellites.reduce((sum, node) => sum + graphNodeSize(node).width + gap.nodeGapX, 0);
  return Math.max(MIN_FAN_RADIUS, graphNodeSize(anchor).height / 2 + 90, arc / FAN_SPAN);
}

/** Lateral room an arc needs for these footprints. */
const arcLength = (laterals: readonly number[]) => laterals.reduce((sum, width) => sum + width + gap.nodeGapX, 0);

/**
 * Fan geometry for every node with satellites, bottom-up: a satellite that carries its own fan is wider on its
 * anchor's arc than its card, and reaches further out, so the anchor's spoke and halo grow with it.
 */
function fanGeometries(graph: Graph, anchorOf: Map<string, string>, satellitesOf: Map<string, string[]>) {
  const byId = new Map(graph.nodes.map(node => [node.id, node]));
  const fans = new Map<string, FanGeometry>();
  const geometry = (id: string): FanGeometry => {
    const known = fans.get(id);
    if (known) return known;
    const node = byId.get(id)!, size = graphNodeSize(node), kids = satellitesOf.get(id) ?? [];
    let result: FanGeometry;
    if (!kids.length) {
      result = {radius: 0, lateral: size.width, reach: 0};
    } else {
      const nested = anchorOf.has(id), spanCap = nested ? NESTED_FAN_SPAN : FAN_SPAN;
      const kidFans = kids.map(geometry), kidSizes = kids.map(kid => graphNodeSize(byId.get(kid)!));
      const arc = arcLength(kidFans.map(fan => fan.lateral));
      const radius = Math.max(MIN_FAN_RADIUS, size.height / 2 + 90, arc / spanCap);
      const span = kids.length === 1 ? 0 : Math.min(spanCap, arc / radius);
      const reach = radius + Math.max(...kidFans.map((fan, i) => fan.reach + Math.hypot(kidSizes[i].width, kidSizes[i].height) / 2));
      const lateral = Math.max(size.width, kids.length === 1 ? kidFans[0].lateral : 2 * radius * Math.sin(Math.min(span, Math.PI) / 2) + kidSizes[0].width / 2);
      result = {radius, lateral, reach};
    }
    fans.set(id, result);
    return result;
  };
  graph.nodes.forEach(node => geometry(node.id));
  return fans;
}

/**
 * Splits a component into satellites and skeleton. Fixed nodes are never satellites. Nothing is peeled while a map is
 * being extended or repaired (`incremental`, `repairOnly`), inside named groups, for coarse group graphs
 * (`nodeSizes`) or for a pure star, which has its own layout.
 */
export function peelSatellites(graph: Graph, options: LayoutOptions): PeeledGraph {
  const classHubs = classHubsOf(graph);
  const none = (): PeeledGraph => ({skeleton: graph, anchorOf: new Map(), satellitesOf: new Map(), halos: new Map(), fans: new Map(), classHubs});
  if (options.incremental || options.repairOnly || options.groups?.length || options.nodeSizes ||
      graph.nodes.length < 2 || isPureStar(graph)) return none();
  // A type link to a class hub says what a node is, not where it belongs: it neither keeps the node in the skeleton
  // nor makes the class a satellite.
  const {neighbors} = adjacency(graph, edge => edge.predicate === RDF_TYPE && classHubs.has(edge.target));
  const n = graph.nodes.length;
  const fixed = graph.nodes.map(node => layoutNodeFixed(node, options) || classHubs.has(node.id));
  const anchor = new Int32Array(n).fill(-1);
  const subtree = new Int32Array(n).fill(1);
  let remaining = n, changed = true;
  while (changed) {
    changed = false;
    for (let i = 0; i < n; i++) {
      if (anchor[i] !== -1 || fixed[i] || subtree[i] > SATELLITE_SUBTREE_LIMIT || remaining <= 1) continue;
      let free = -1, count = 0;
      for (const j of neighbors[i]) if (anchor[j] === -1) {free = j; count++;}
      if (count !== 1) continue;
      anchor[i] = free;
      subtree[free] += subtree[i];
      remaining--;
      changed = true;
    }
  }
  if (remaining === n) return none();
  const anchorOf = new Map<string, string>(), satellitesOf = new Map<string, string[]>();
  graph.nodes.forEach((node, i) => {
    if (anchor[i] === -1) return;
    const owner = graph.nodes[anchor[i]].id;
    anchorOf.set(node.id, owner);
    const list = satellitesOf.get(owner);
    if (list) list.push(node.id);
    else satellitesOf.set(owner, [node.id]);
  });
  const skeletonNodes = graph.nodes.filter((_, i) => anchor[i] === -1);
  const skeletonIds = new Set(skeletonNodes.map(node => node.id));
  const skeleton: Graph = {...graph, nodes: skeletonNodes,
    edges: graph.edges.filter(edge => skeletonIds.has(edge.source) && skeletonIds.has(edge.target))};
  const fans = fanGeometries(graph, anchorOf, satellitesOf);
  const halos = new Map<string, number>();
  for (const node of skeletonNodes) {
    const satellites = satellitesOf.get(node.id);
    if (!satellites?.length) continue;
    const fan = fans.get(node.id)!;
    // The square reserved in the force layout: the spoke with margin, plus half of what the sub-fans add outward.
    halos.set(node.id, fan.radius * HALO_SCALE + (fan.reach - fan.radius) / 2);
  }
  return {skeleton, anchorOf, satellitesOf, halos, fans, classHubs};
}

/** Neighbours considered per node when looking for shared neighbours; bounds the work on hubs. */
const SIMILARITY_NEIGHBOR_LIMIT = 48;
const SIMILARITY_IDEAL_LENGTH = 40;
const SIMILARITY_ELASTICITY = 0.2;
/** Shared neighbours count 1/log2(1 + degree) each (Adamic–Adar): a hub everyone links to says nothing about similarity. */
const SIMILARITY_MIN_WEIGHT = 0.3;

export type LayoutSpring = {source: string; target: string; ideal: number; elasticity: number};

/**
 * Force-layout springs between skeleton nodes of the same first type that share at least one neighbour: nodes that
 * play the same role end up side by side. They are never statements, never drawn, scored or routed.
 */
export function similaritySprings(graph: Graph, peeled: PeeledGraph): LayoutSpring[] {
  const skeleton = peeled.skeleton;
  const {neighbors} = adjacency(skeleton);
  const typeOf = skeleton.nodes.map(node => node.types?.[0]?.id ?? '');
  const shared = new Map<string, number>();
  skeleton.nodes.forEach((node, v) => {
    if (!typeOf[v]) return;
    let seen = 0;
    for (const w of neighbors[v]) {
      if (seen++ >= SIMILARITY_NEIGHBOR_LIMIT) break;
      const weight = 1 / Math.log2(1 + neighbors[w].size);
      let inner = 0;
      for (const u of neighbors[w]) {
        if (inner++ >= SIMILARITY_NEIGHBOR_LIMIT) break;
        if (u <= v || typeOf[u] !== typeOf[v]) continue;
        const key = `${v}:${u}`;
        shared.set(key, (shared.get(key) ?? 0) + weight);
      }
    }
  });
  return [...shared]
    .filter(([, weight]) => weight >= SIMILARITY_MIN_WEIGHT)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([key, weight]) => {
      const [v, u] = key.split(':').map(Number);
      return {source: skeleton.nodes[v].id, target: skeleton.nodes[u].id, ideal: SIMILARITY_IDEAL_LENGTH, elasticity: SIMILARITY_ELASTICITY * weight};
    });
}

type Segment = [PointerPosition, PointerPosition];

function segmentsCross(a: PointerPosition, b: PointerPosition, c: PointerPosition, d: PointerPosition) {
  const ccw = (p: PointerPosition, q: PointerPosition, r: PointerPosition) => (r.y - p.y) * (q.x - p.x) > (q.y - p.y) * (r.x - p.x);
  return ccw(a, c, d) !== ccw(b, c, d) && ccw(a, b, c) !== ccw(a, b, d);
}

/**
 * Places every satellite around its anchor, into the widest angle between the anchor's placed neighbours, ordered by
 * the predicate that links them to the anchor, then their first type, with literals last. The fan's centre is shifted
 * within that angle when it would cross placed spokes or land on placed cards. Anchors with more satellites go first;
 * a satellite that has satellites of its own fans them outward. Fixed satellites keep their coordinates.
 */
export function placeSatellites(graph: Graph, positions: Map<string, PointerPosition>, peeled: PeeledGraph, options: LayoutOptions) {
  const byId = new Map(graph.nodes.map(node => [node.id, node]));
  // The direction to a class hub is not an occupied direction: fans face away from structural neighbours only.
  const {index, neighbors} = adjacency(graph, edge => edge.predicate === RDF_TYPE && peeled.classHubs.has(edge.target));
  const predicateTo = new Map<string, string>();
  for (const edge of graph.edges.slice().sort((a, b) => a.id.localeCompare(b.id))) {
    for (const [self, other] of [[edge.source, edge.target], [edge.target, edge.source]]) {
      if (peeled.anchorOf.get(self) === other && !predicateTo.has(self)) predicateTo.set(self, edge.predicate);
    }
  }
  const sortKey = (id: string) => {
    const node = byId.get(id)!;
    return `${predicateTo.get(id) ?? ''}\u0000${node.types?.[0]?.id ?? '\uffff'}\u0000${node.kind === 'literal' ? 1 : 0}\u0000${node.label}\u0000${id}`;
  };
  const placed: Segment[] = [];
  for (const edge of peeled.skeleton.edges) {
    const a = positions.get(edge.source), b = positions.get(edge.target);
    if (a && b && edge.source !== edge.target) placed.push([a, b]);
  }
  const cardNear = (p: PointerPosition, exclude: Set<string>) => {
    let penalty = 0;
    for (const [id, q] of positions) {
      if (exclude.has(id)) continue;
      const size = graphNodeSize(byId.get(id)!);
      if (Math.abs(q.x - p.x) < size.width / 2 + 80 && Math.abs(q.y - p.y) < size.height / 2 + 60) penalty += 0.7;
    }
    return penalty;
  };

  const place = (anchorId: string) => {
    const kids = (peeled.satellitesOf.get(anchorId) ?? []).slice().sort((a, b) => sortKey(a).localeCompare(sortKey(b)));
    const center = positions.get(anchorId);
    if (!center || !kids.length) return;
    const movable = kids.filter(id => !layoutNodeFixed(byId.get(id)!, options));
    const kidSet = new Set(kids);
    const occupied = [...neighbors[index.get(anchorId)!]]
      .map(i => graph.nodes[i].id)
      .filter(id => !kidSet.has(id) || (positions.has(id) && !movable.includes(id)))
      .flatMap(id => {const p = positions.get(id); return p ? [Math.atan2(p.y - center.y, p.x - center.x)] : [];})
      .sort((a, b) => a - b);
    if (movable.length) {
      let gapStart = 0, gapSize = Math.PI * 2;
      if (occupied.length) {
        gapSize = 0;
        occupied.forEach((a, i) => {
          const next = i + 1 < occupied.length ? occupied[i + 1] : occupied[0] + Math.PI * 2;
          if (next - a > gapSize) {gapSize = next - a; gapStart = a;}
        });
      }
      const fullCircle = !occupied.length;
      const cards = movable.map(id => byId.get(id)!), sizes = cards.map(graphNodeSize);
      const anchorSize = graphNodeSize(byId.get(anchorId)!);
      const arc = arcLength(movable.map(id => peeled.fans.get(id)?.lateral ?? graphNodeSize(byId.get(id)!).width));
      const spanCap = peeled.anchorOf.has(anchorId) ? NESTED_FAN_SPAN : FAN_SPAN;
      const available = fullCircle ? Math.PI * 2 : Math.max(0.3, Math.min(spanCap, gapSize - FAN_MARGIN * 2));
      const rings = Math.max(1, Math.ceil(Math.sqrt(movable.length / SINGLE_RING_LIMIT)));
      const stride = Math.max(...sizes.map(size => Math.hypot(size.width + gap.nodeGapX, size.height + gap.nodeGapY)));
      const radius = Math.max(MIN_FAN_RADIUS, anchorSize.height / 2 + 90, arc / rings / available);
      const span = fullCircle ? Math.PI * 2 : Math.min(available, arc / rings / radius);
      const bisector = fullCircle ? 0 : gapStart + gapSize / 2;
      const proposal = (centerAngle: number) => {
        const result: PointerPosition[] = [];
        let offset = 0;
        for (let ring = 0; ring < rings; ring++) {
          const count = Math.ceil((movable.length - offset) / (rings - ring));
          const r = radius + ring * stride;
          for (let k = 0; k < count; k++) {
            const angle = fullCircle
              ? centerAngle + ((k + (ring % 2) * .5) / count) * Math.PI * 2
              : movable.length === 1 ? centerAngle : centerAngle - span / 2 + ((k + .5 + (ring % 2) * .25) / count) * span;
            result.push({x: center.x + Math.cos(angle) * r, y: center.y + Math.sin(angle) * r});
          }
          offset += count;
        }
        return result;
      };
      let bestCost = Number.POSITIVE_INFINITY, bestPoints: PointerPosition[] = [];
      const limit = fullCircle ? 0 : Math.max(0, (gapSize - span) / 2 - FAN_MARGIN);
      const step = Math.max(0.05, limit / 6);
      const offsets = [0];
      for (let d = step; d <= limit + 1e-9; d += step) offsets.push(-d, d);
      const exclude = new Set([anchorId, ...kids]);
      for (const d of offsets) {
        const points = proposal(bisector + d);
        let cost = Math.abs(d) * 0.1;
        for (const p of points) {
          for (const [a, b] of placed) if (a !== center && b !== center && segmentsCross(center, p, a, b)) cost += 1;
          cost += cardNear(p, exclude);
        }
        if (cost < bestCost) {bestCost = cost; bestPoints = points;}
      }
      movable.forEach((id, i) => {
        positions.set(id, bestPoints[i]);
        placed.push([center, bestPoints[i]]);
      });
    }
    kids.forEach(id => {
      if (!positions.has(id)) positions.set(id, {x: center.x, y: center.y});
      place(id);
    });
  };
  const anchors = [...peeled.satellitesOf.keys()]
    .filter(id => !peeled.anchorOf.has(id))
    .sort((a, b) => (peeled.satellitesOf.get(b)?.length ?? 0) - (peeled.satellitesOf.get(a)?.length ?? 0) || a.localeCompare(b));
  anchors.forEach(place);
  for (const node of graph.nodes) {
    if (positions.has(node.id)) continue;
    const owner = peeled.anchorOf.get(node.id);
    positions.set(node.id, (owner ? positions.get(owner) : undefined) ?? {x: node.x ?? 0, y: node.y ?? 0});
  }
  placeClassHubs(graph, positions, peeled, options);
}

/** Card pairs closer than this (centre distance per axis beyond the half-sizes) break overlap removal's clearance. */
const tooClose = (a: PointerPosition, as: {width: number; height: number}, b: PointerPosition, bs: {width: number; height: number}) =>
  Math.abs(a.x - b.x) < (as.width + bs.width) / 2 + gap.nodeGapX && Math.abs(a.y - b.y) < (as.height + bs.height) / 2 + gap.nodeGapY;

/**
 * A class hub sits among its instances, at the spot near their centroid that the fewest links run through and no card
 * crowds; the readability pass never moves a node with that many links, and overlap removal only keeps it off cards.
 */
export function placeClassHubs(graph: Graph, positions: Map<string, PointerPosition>, peeled: PeeledGraph, options: LayoutOptions) {
  if (!peeled.classHubs.size) return;
  const byId = new Map(graph.nodes.map(node => [node.id, node]));
  const segments = graph.edges.flatMap(edge => {
    if (edge.predicate === RDF_TYPE && peeled.classHubs.has(edge.target)) return [];
    const a = positions.get(edge.source), b = positions.get(edge.target);
    return a && b && edge.source !== edge.target ? [[a, b] as const] : [];
  });
  for (const id of [...peeled.classHubs].sort()) {
    const node = byId.get(id);
    if (!node || layoutNodeFixed(node, options)) continue;
    const members = graph.edges.flatMap(edge => (edge.predicate === RDF_TYPE && edge.target === id ? [positions.get(edge.source)] : [])).filter((p): p is PointerPosition => Boolean(p));
    if (!members.length) continue;
    const centroid = {x: members.reduce((sum, p) => sum + p.x, 0) / members.length, y: members.reduce((sum, p) => sum + p.y, 0) / members.length};
    const size = graphNodeSize(node);
    const candidates: PointerPosition[] = [centroid];
    for (const r of [140, 280, 420]) for (let k = 0; k < 8; k++) candidates.push({x: centroid.x + Math.cos((k / 8) * Math.PI * 2) * r, y: centroid.y + Math.sin((k / 8) * Math.PI * 2) * r});
    let best = centroid, bestCost = Number.POSITIVE_INFINITY;
    for (const p of candidates) {
      const bounds = {minX: p.x - size.width / 2 - gap.nodeGapX / 2, minY: p.y - size.height / 2 - gap.nodeGapY / 2, maxX: p.x + size.width / 2 + gap.nodeGapX / 2, maxY: p.y + size.height / 2 + gap.nodeGapY / 2};
      let cost = Math.hypot(p.x - centroid.x, p.y - centroid.y) / 400;
      for (const [other, q] of positions) {
        if (other === id) continue;
        const otherSize = graphNodeSize(byId.get(other)!);
        if (Math.abs(q.x - p.x) < otherSize.width / 2 + size.width / 2 + 32 && Math.abs(q.y - p.y) < otherSize.height / 2 + size.height / 2 + 24) cost += 0.7;
      }
      for (const [a, b] of segments) if (segmentIntersectsBounds(a, b, bounds)) cost += 1;
      if (cost < bestCost) {bestCost = cost; best = p;}
    }
    positions.set(id, best);
  }
}

/**
 * Fans are sized for their widest case, so a drawing of nested fans is roomier than it needs to be. Widens every fan
 * into the free angle around its anchor (shorter spokes for the same arc), shrinks fans toward their anchors, and
 * slides every skeleton node, with all its satellites, toward its skeleton neighbours: each step only as far as
 * overlap removal's clearance allows without adding a crossing or an edge through a card. Deepest fans go first.
 */
export function compactFans(graph: Graph, positions: Map<string, PointerPosition>, peeled: PeeledGraph, options: LayoutOptions) {
  if (!peeled.anchorOf.size || graph.nodes.length > 350) return;
  const sizes = new Map(graph.nodes.map(node => [node.id, graphNodeSize(node)]));
  const fixed = new Set(graph.nodes.filter(node => layoutNodeFixed(node, options)).map(node => node.id));
  const edges = graph.edges.filter(edge => edge.source !== edge.target && positions.has(edge.source) && positions.has(edge.target) &&
    !(edge.predicate === RDF_TYPE && peeled.classHubs.has(edge.target)));
  const edgeIndex = new Map(edges.map((edge, i) => [edge, i]));
  const neighbours = new Map<string, string[]>();
  for (const edge of edges) {
    neighbours.set(edge.source, [...(neighbours.get(edge.source) ?? []), edge.target]);
    neighbours.set(edge.target, [...(neighbours.get(edge.target) ?? []), edge.source]);
  }
  const descendants = new Map<string, string[]>();
  const subtree = (id: string): string[] => {
    const known = descendants.get(id);
    if (known) return known;
    const result = (peeled.satellitesOf.get(id) ?? []).flatMap(child => [child, ...subtree(child)]);
    descendants.set(id, result);
    return result;
  };
  const depth = (id: string) => {let d = 0; for (let at = peeled.anchorOf.get(id); at; at = peeled.anchorOf.get(at)) d++; return d;};
  const skeletonIds = new Set(peeled.skeleton.nodes.map(node => node.id));
  const maxHalf = Math.max(...[...sizes.values()].map(size => Math.max(size.width, size.height))) + gap.nodeGapX;
  const crosses = (a: PointerPosition, b: PointerPosition, c: PointerPosition, d: PointerPosition) => {
    if (Math.max(a.x, b.x) < Math.min(c.x, d.x) || Math.max(c.x, d.x) < Math.min(a.x, b.x) ||
        Math.max(a.y, b.y) < Math.min(c.y, d.y) || Math.max(c.y, d.y) < Math.min(a.y, b.y)) return false;
    const o = (p: PointerPosition, q: PointerPosition, r: PointerPosition) => (q.x - p.x) * (r.y - p.y) - (q.y - p.y) * (r.x - p.x);
    return o(a, b, c) * o(a, b, d) < -1e-6 && o(c, d, a) * o(c, d, b) < -1e-6;
  };
  const through = (a: PointerPosition, b: PointerPosition, id: string, at: PointerPosition) => {
    const size = sizes.get(id)!;
    if (Math.max(a.x, b.x) < at.x - size.width / 2 || Math.min(a.x, b.x) > at.x + size.width / 2 ||
        Math.max(a.y, b.y) < at.y - size.height / 2 || Math.min(a.y, b.y) > at.y + size.height / 2) return false;
    return segmentIntersectsBounds(a, b, {minX: at.x - size.width / 2, minY: at.y - size.height / 2, maxX: at.x + size.width / 2, maxY: at.y + size.height / 2});
  };
  /** Conflicts a move of `moved` can change: pairs and edge–card pairs with a moved part; Infinity on a clash. */
  const localConflicts = (moved: Set<string>, at: (id: string) => PointerPosition, limit = Number.POSITIVE_INFINITY) => {
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (const id of moved) {const p = at(id); minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x); minY = Math.min(minY, p.y); maxY = Math.max(maxY, p.y);}
    for (const [other, q0] of positions) {
      const q = moved.has(other) ? at(other) : q0;
      if (q.x < minX - maxHalf || q.x > maxX + maxHalf || q.y < minY - maxHalf || q.y > maxY + maxHalf) continue;
      const otherSize = sizes.get(other)!;
      for (const id of moved) if (id !== other && tooClose(at(id), sizes.get(id)!, q, otherSize)) return Number.POSITIVE_INFINITY;
    }
    let count = 0;
    for (const edge of edges) {
      if (!moved.has(edge.source) && !moved.has(edge.target)) continue;
      const a = at(edge.source), b = at(edge.target), index = edgeIndex.get(edge)!;
      for (const other of edges) {
        if (other === edge || other.source === edge.source || other.source === edge.target || other.target === edge.source || other.target === edge.target) continue;
        if ((moved.has(other.source) || moved.has(other.target)) && edgeIndex.get(other)! < index) continue;
        if (crosses(a, b, at(other.source), at(other.target))) count++;
      }
      for (const id of sizes.keys()) if (id !== edge.source && id !== edge.target && positions.has(id) && through(a, b, id, at(id))) count++;
      if (count > limit) return count;
    }
    for (const edge of edges) {
      if (moved.has(edge.source) || moved.has(edge.target)) continue;
      const a = positions.get(edge.source)!, b = positions.get(edge.target)!;
      for (const id of moved) if (through(a, b, id, at(id))) count++;
      if (count > limit) return count;
    }
    return count;
  };
  /** Tries the proposals in order and keeps the first that clears the cards, adds no conflict and passes `valid`. */
  const tryMoves = (moved: Set<string>, proposals: Array<(id: string, p: PointerPosition) => PointerPosition>,
    valid: (at: (id: string) => PointerPosition) => boolean = () => true) => {
    if ([...moved].some(id => fixed.has(id))) return false;
    const before = localConflicts(moved, id => positions.get(id)!);
    for (const proposal of proposals) {
      const next = new Map([...moved].map(id => [id, proposal(id, positions.get(id)!)]));
      const at = (id: string) => next.get(id) ?? positions.get(id)!;
      if (!valid(at)) continue;
      if (localConflicts(moved, at, before) > before) continue;
      next.forEach((p, id) => positions.set(id, p));
      return true;
    }
    return false;
  };
  const turn = (p: PointerPosition, c: PointerPosition, angle: number) => ({
    x: c.x + (p.x - c.x) * Math.cos(angle) - (p.y - c.y) * Math.sin(angle),
    y: c.y + (p.x - c.x) * Math.sin(angle) + (p.y - c.y) * Math.cos(angle),
  });
  /** Proposals that open a fan into its free angle: arc length kept, spokes shortened, sub-fans carried along. */
  const spreads = (anchor: string) => {
    const centre = positions.get(anchor)!, kids = (peeled.satellitesOf.get(anchor) ?? []).filter(id => positions.has(id));
    if (kids.length < 2) return [];
    const kidSet = new Set(kids);
    const angleOf = (id: string) => Math.atan2(positions.get(id)!.y - centre.y, positions.get(id)!.x - centre.x);
    const mean = Math.atan2(kids.reduce((sum, id) => sum + Math.sin(angleOf(id)), 0), kids.reduce((sum, id) => sum + Math.cos(angleOf(id)), 0));
    const offsets = new Map(kids.map(id => [id, Math.atan2(Math.sin(angleOf(id) - mean), Math.cos(angleOf(id) - mean))]));
    const span = Math.max(...offsets.values()) - Math.min(...offsets.values());
    if (span < 0.2) return [];
    const occupied = (neighbours.get(anchor) ?? []).filter(id => !kidSet.has(id)).map(id => {
      const q = positions.get(id)!; return Math.atan2(q.y - centre.y, q.x - centre.x);
    });
    const room = occupied.length ? Math.min(...occupied.map(a => Math.abs(Math.atan2(Math.sin(a - mean), Math.cos(a - mean))))) : Math.PI;
    const widest = Math.min(Math.PI * 2 - (Math.PI * 2) / kids.length, 2 * (room - FAN_MARGIN));
    const radius = kids.reduce((sum, id) => sum + Math.hypot(positions.get(id)!.x - centre.x, positions.get(id)!.y - centre.y), 0) / kids.length;
    const owner = new Map<string, string>();
    for (const kid of kids) for (const d of [kid, ...subtree(kid)]) owner.set(d, kid);
    // Neighbouring satellites keep their distance (the chord, not the arc: a wider angle needs a little more radius).
    const step = span / (kids.length - 1);
    return [1.6, 1.3, 1.12].flatMap(factor => {
      const wider = Math.min(widest, span * factor);
      if (wider <= span * 1.02) return [];
      const shorter = Math.max(MIN_FAN_RADIUS, radius * Math.sin(step / 2) / Math.sin(wider / (kids.length - 1) / 2));
      return [(id: string, p: PointerPosition) => {
        const kid = owner.get(id)!, delta = offsets.get(kid)! * (wider / span - 1);
        const turned = turn(p, centre, delta), kidAngle = mean + offsets.get(kid)! * wider / span;
        return {x: turned.x + Math.cos(kidAngle) * (shorter - radius), y: turned.y + Math.sin(kidAngle) * (shorter - radius)};
      }];
    });
  };
  /** Longest spoke from a node to its own satellites (0 without satellites). */
  const spoke = (id: string) => {
    const centre = positions.get(id)!;
    return Math.max(0, ...(peeled.satellitesOf.get(id) ?? []).map(kid => Math.hypot(positions.get(kid)!.x - centre.x, positions.get(kid)!.y - centre.y)));
  };
  const anchors = [...peeled.satellitesOf.keys()].filter(id => positions.has(id)).sort((a, b) => depth(b) - depth(a) || a.localeCompare(b));
  const bodies = [...skeletonIds].filter(id => (neighbours.get(id) ?? []).some(other => skeletonIds.has(other)) && !peeled.classHubs.has(id)).sort();
  for (let pass = 0; pass < 4; pass++) {
    let movedAny = false;
    for (const anchor of anchors) {
      const moved = new Set(subtree(anchor));
      if (tryMoves(moved, spreads(anchor))) movedAny = true;
      const centre = positions.get(anchor)!;
      if (tryMoves(moved, [0.55, 0.7, 0.8, 0.9].map(s => (_id: string, p: PointerPosition) => ({x: centre.x + (p.x - centre.x) * s, y: centre.y + (p.y - centre.y) * s})))) movedAny = true;
    }
    for (const body of bodies) {
      const linked = (neighbours.get(body) ?? []).filter(id => skeletonIds.has(id));
      const around = linked.map(id => positions.get(id)!);
      const target = {x: around.reduce((sum, p) => sum + p.x, 0) / around.length, y: around.reduce((sum, p) => sum + p.y, 0) / around.length};
      const from = positions.get(body)!;
      const separated = (at: (id: string) => PointerPosition) => linked.every(other => {
        const needed = HUB_SEPARATION * Math.max(spoke(body), spoke(other));
        return !needed || Math.hypot(at(body).x - at(other).x, at(body).y - at(other).y) >= needed;
      });
      if (tryMoves(new Set([body, ...subtree(body)]), [0.5, 0.3, 0.15, 0.08].map(f => (_id: string, p: PointerPosition) => ({x: p.x + (target.x - from.x) * f, y: p.y + (target.y - from.y) * f})), separated)) movedAny = true;
    }
    if (!movedAny) break;
  }
  placeClassHubs(graph, positions, peeled, options);
}
